import{z as B,x as A,o as E,c,q as n,j as i,D as e,d as t,s,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"随机占优预备","description":"","frontmatter":{"title":"随机占优预备","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/stochastic-order-prep.md","filePath":"econ/stochastic-order-prep.md","lastUpdated":1791063341000}'),d={name:"econ/stochastic-order-prep.md"};function p(D,a,h,S,F,f){const o=A("Mermaid");return E(),c("div",null,[a[2]||(a[2]=n('<h1 id="随机占优预备" tabindex="-1">随机占优预备 <a class="header-anchor" href="#随机占优预备" aria-label="Permalink to &quot;随机占优预备&quot;">​</a></h1><div class="epigraph"><p>两条分布谁更「好」，可以先在 cdf 上比较，不必先有一套期望效用数字。</p><footer>—— 据 Mas-Colell, Whinston and Green, Microeconomic Theory 第 6 章；Rothschild and Stiglitz, &quot;Increasing Risk,&quot; Journal of Economic Theory, 1970 整理</footer></div><p>上一课<a href="/econ/lln-clt">大数定律与中心极限</a>比较的是许多拷贝的平均与极限律。决策者面对的是<strong>两条</strong>彩票、两种收入分布，拷贝数是一，LLN 帮不上。缺口是随机序：用 cdf 的积分说出「所有单调者都同意」或「所有厌恶风险者都同意」。本课只预备这些序。下一课起进入微观主干：<a href="/econ/preference-choice">偏好、完备与传递</a>。效用函数、vNM 公理、风险厌恶的阿罗–普拉特，都不在本课重写——边界交给偏好公理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实值随机变量 \\(X,Y\\)，cdf 为 \\(F,G\\)。<strong>一阶随机占优</strong>（FSD）：\\(F(t)\\le G(t)\\) 对一切 \\(t\\)，即 \\(X\\) 的质量更靠右。若后再有期望效用，一切非减 \\(u\\) 给出 \\(\\mathbb{E}u(X)\\ge\\mathbb{E}u(Y)\\)；本课把这条当作序与单调函数的积分刻画，不把 \\(u\\) 解释成已证明的效用表示。<strong>二阶随机占优</strong>（SSD）：\\(\\int_{-\\infty}^t(G-F)\\ge 0\\) 对一切 \\(t\\)（等均值时即均值保持展开的积分形式）。积分刻画对应凹的 \\(u\\)。Rothschild–Stiglitz 的「风险更大」是等均值的 SSD 劣势。</p><p>均值–方差只在正态或二次 \\(u\\) 上与 SSD 对齐。一般分布，方差大不必被厌恶风险者讨厌（可能右尾补偿）。后课<a href="/econ/mean-variance-eu">均值方差何时等于 EU</a>再收窄；本课不要用 \\(\\sigma\\) 代替随机序。</p><h3 id="占优不是偏好公理" tabindex="-1">占优不是偏好公理 <a class="header-anchor" href="#占优不是偏好公理" aria-label="Permalink to &quot;占优不是偏好公理&quot;">​</a></h3><p>FSD/SSD 比较的是给定的概率分布，不是决策者会不会比较任意两个菜单。完备、传递、连续，是下一课对<strong>备选集上的二元关系</strong>提出的要求。可以把占优想成「若偏好后来满足单调或风险厌恶，则必须尊重这些序」，但本课不倒过来从占优推出偏好。也不把占优写成资产定价的状态价格——那是完全市场后课。</p><p><span class="marginnote">FSD 不要求均值相等，SSD 的风险比较常加等均值。FSD \\(\\Rightarrow\\) 均值更大（在积分存在时），但均值更大远远不够 FSD。</span></p><p><span class="marginnote">直觉类比：cdf 是「考不到 t 分的概率」。若 F 的曲线处处压在 G 之下，等于任选一条及格线 t，X 挂科的可能性都更小——根本不必知道考试怎么给分（效用长什么样），X 已经更稳。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>积分检验：FSD 看 \\(G-F\\) 非负；SSD 看 \\(G-F\\) 的累积非负。离散分布用手算阶梯 cdf。连续密度则看生存函数或分位数：\\(X\\) 一阶占优 \\(Y\\) 当且仅当分位数函数 \\(F^{-1}(q)\\ge G^{-1}(q)\\) 对一切 \\(q\\)。构造：给 \\(Y\\) 加上一个正的随机项（不必独立）可得到 FSD；等均值下加噪声（均值保持展开）得到 SSD 劣势。</p><p>与条件期望的接口：\\(\\mathbb{E}[X\\mid Y]=Y\\) 且 \\(X\\neq Y\\) 时，\\(X\\) 是 \\(Y\\) 的均值保持展开，\\(Y\\) 二阶占优 \\(X\\)。这是「信息更多未必风险更小」的反面：多一层噪声变差。后课<a href="/econ/sosd-mps">二阶占优与均值保持展开</a>会展开；本课只留定义。</p><p><span class="marginnote">数字实例：X 以 0.7 得 100、0.3 得 0；Y 以 0.5 得 100、0.5 得 0。在 \\(0\\le t\\lt 100\\) 的每一点都有 \\(F(t)=0.3\\lt 0.5=G(t)\\)，其余点两者相等——F 处处不高于 G，X 一阶占优 Y，全程没碰任何效用函数。</span></p>',14)),(E(),i(l,null,{default:e(()=>[s(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20CDF%5B%22%E4%B8%A4%E6%9D%A1%20cdf%22%5D%20--%3E%20FSD%5B%22%E4%B8%80%E9%98%B6%EF%BC%9A%E8%B4%A8%E9%87%8F%E6%9B%B4%E5%8F%B3%22%5D%0A%20%20CDF%20--%3E%20SSD%5B%22%E4%BA%8C%E9%98%B6%EF%BC%9A%E7%B4%AF%E7%A7%AF%20cdf%20%E6%9B%B4%E5%B0%8F%22%5D%0A%20%20FSD%20--%3E%20MON%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8D%95%E8%B0%83%E5%81%8F%E5%A5%BD%E5%B0%8A%E9%87%8D%20FSD%22%5D%0A%20%20SSD%20--%3E%20RA%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%E5%B0%8A%E9%87%8D%20SSD%22%5D%0A%20%20PREP%5B%22%E6%95%B0%E5%AD%A6%E5%9F%BA%E7%A1%80%E8%AF%BE%E6%94%B6%E6%9D%9F%22%5D%20--%3E%20AX%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%81%8F%E5%A5%BD%E5%85%AC%E7%90%86%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"为什么 cdf 点点更小就是「更好」：对每个阈值 \\(t\\)，落到 \\(t\\) 以下的概率更低，所有「超过 \\(t\\) 就算成功」的单调计数都同意。二阶把「成功」改成对阈值的积分，等价于对凹变换平均——凹惩罚分散。没有偏好理论也能做这两条积分比较；偏好理论稍后决定决策者是不是「所有单调者」或「所有凹者」中的一员。",-1)),(E(),i(l,null,{default:e(()=>[s(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E9%80%89%E4%B8%80%E4%B8%AA%E9%98%88%E5%80%BC%20t%22%5D%20--%3E%20A%5B%22%E7%9C%8B%20X%20%E8%90%BD%E5%9C%A8%20t%20%E4%BB%A5%E4%B8%8B%E7%9A%84%E6%A6%82%E7%8E%87%20F(t)%22%5D%0A%20%20T%20--%3E%20B%5B%22%E7%9C%8B%20Y%20%E8%90%BD%E5%9C%A8%20t%20%E4%BB%A5%E4%B8%8B%E7%9A%84%E6%A6%82%E7%8E%87%20G(t)%22%5D%0A%20%20A%20--%3E%20CMP%5B%22%E9%80%90%E7%82%B9%E6%AF%94%E8%BE%83%20F(t)%20%E4%B8%8E%20G(t)%22%5D%0A%20%20B%20--%3E%20CMP%0A%20%20CMP%20--%3E%7C%22F(t)%20%E2%89%A4%20G(t)%20%E5%A4%84%E5%A4%84%E6%88%90%E7%AB%8B%22%7C%20WIN%5B%22%E6%89%80%E6%9C%89%E3%80%8C%E8%B6%85%E8%BF%87%20t%20%E6%89%8D%E7%AE%97%E6%88%90%E5%8A%9F%E3%80%8D%E7%9A%84%E6%A3%80%E9%AA%8C%E9%83%BD%E5%81%8F%E5%90%91%20X%22%5D%0A%20%20CMP%20--%3E%7C%22%E6%9C%89%E6%9F%90%E4%B8%AA%20t%20%E5%8F%8D%E8%BD%AC%22%7C%20LOSE%5B%22%E4%B8%80%E9%98%B6%E5%8D%A0%E4%BC%98%E4%B8%8D%E6%88%90%E7%AB%8B%EF%BC%8C%E9%80%80%E5%88%B0%E4%BA%8C%E9%98%B6%E7%A7%AF%E5%88%86%E6%A3%80%E9%AA%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p>数学与优化基础课在此结束。拓扑、凸、分离、KKT、包络、不动点、贝尔曼、条件期望、随机序，后课将默认已经可用。微观从比较关系 \\(\\succsim\\) 起笔，不再从开集或 cdf 起笔。</p><p><span class="marginnote">三阶占优接谨慎（\\(u&#39;&#39;&#39;\\gt 0\\)），本课不写。非期望效用可以不尊重 SSD，那是后课对照，不是本课的反例作业。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不在本课写 vNM 公理、不证明效用表示、不定义阿罗–普拉特系数。不进入限价簿、不写 CAPM 实证、不把随机序说成投资组合优化软件。下一课<a href="/econ/preference-choice">偏好、完备与传递</a>是微观主干第一课：对象换成菜单上的排序，随机占优作为后续风险课的约束再回来。</p><p><span class="marginnote">常见误区：初学者容易把二阶占优当成「更宽松所以更好用」的万能比较。注意「更有风险」这个解释只在等均值时成立；均值不同时，SSD 可能只是说一个分布更稳定，而不是整体更好，别急着替它颁奖。</span></p><p>后课默认：会用 cdf 检验 FSD/SSD；讨论风险态度时，SSD 是「所有凹变换都同意」的候选序；偏好本身从公理开始讲。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FSD：cdf 点点更小；对应一切非减变换的积分比较。</li><li>SSD：cdf 积分占优；等均值时即「更少分散」。</li><li>占优是分布上的序，不是完备传递的偏好公理。</li><li>均值–方差不能代替 SSD。</li><li>下一课：<a href="/econ/preference-choice">偏好、完备与传递</a>。</li><li>出处：MWG 第 6 章；Rothschild and Stiglitz, <em>JET</em> 1970。</li></ul>',8))])}const u=B(d,[["render",p]]);export{C as __pageData,u as default};
